import React from "react";
import { Preview } from "@storybook/react";
import { MINIMAL_VIEWPORTS } from "@storybook/addon-viewport";
import "glightbox/dist/css/glightbox.min.css";
import "@airbus/icons/dist/webfont/airbus-icons.css";
import ThemeProvider from "../src/lib/styling/ThemeProvider";
import DocsContainer from "./DocsContainer.tsx";

let defaultTheme;
try {
  defaultTheme = localStorage.getItem("ds-theme") || "airbus";
} catch (err) {
  console.error(err);
}

const preview: Preview = {
  globalTypes: {
    theme: {
      description: "Choose Brand",
      defaultValue: defaultTheme,
      toolbar: {
        icon: "flag",
        title: "Theme",
        items: [
          { value: "airbus", title: "airbus" },
          { value: "skywise", title: "skywise" },
        ],
        dynamicTitle: true,
      },
    },
  },
  initialGlobals: {
    theme: "airbus",
  },
  parameters: {
    viewMode: "docs", // Can be 'story', 'docs', or 'canvas'
    options: {
      storySort: {
        method: "alphabetical",
        order: [
          "General",
          [
            "Welcome",
            "Known Issues",
            "Migration",
            "Visual Styles",
            ["Introduction", "Tokens", "Icons", "Typography"],
            "Layout",
            "Forms",
            ["Introduction", "Form Control", "Examples"],
            "Templates",
          ],
          "Components",
          "Building Blocks",
        ],
      },
    },
    controls: {
      sort: "alpha",
      matchers: {
        color: /(background|color)$/i,
        date: /Date$/,
      },
    },
    viewport: {
      viewports: MINIMAL_VIEWPORTS, // newViewports would be an ViewportMap. (see below for examples)
    },
    docs: {
      container: DocsContainer,
      toc: { headingSelector: "h2, h3" },
      source: {
        type: "dynamic",
        // transform function will be used for stories with type: "code"
        // Storybook "Show code" snippet normalizer.
        //
        // We keep `type: "dynamic"` so Storybook can auto-generate a snippet.
        // But when the CSF story is exported as an object with `render: (...) => { ... }`,
        // Storybook's dynamic source can include a lot of wrapper noise.
        //
        // This transform extracts the *block body* of a story's `render:` function
        // (when present) so the docs snippet is closer to what authors wrote.
        transform: (code: string) => {
          // Only attempt extraction when the story code contains `render:`.
          const renderStart = code.indexOf("render:");
          if (renderStart === -1) return code;

          // Find the arrow (`=>`) that starts the `render` function.
          // If we can't find it, we don't try to be clever.
          const arrowIndex = code.indexOf("=>", renderStart);
          if (arrowIndex === -1) return code;

          // Move forward to the first non-whitespace character after the arrow.
          let blockStart = arrowIndex + 2;
          while (blockStart < code.length && /\s/.test(code[blockStart])) {
            blockStart++;
          }

          // Critical guard:
          // - Block body: `render: () => { ... }`  ✅ safe to extract
          // - Expression body: `render: () => ( <JSX/> )` or `render: () => <JSX/>`
          //   In expression bodies there may still be `{` inside JSX props
          //   (e.g. `onClick={() => {}}`). A naive "first `{` after render" approach
          //   will grab the wrong `{` and can yield an empty/invalid snippet.
          if (code[blockStart] !== "{") return code;

          // Simple brace matching to find the end of the render block.
          // This is intentionally lightweight: we only run it when the block starts
          // exactly at the render body (see guard above), which keeps false matches low.
          let braceCount = 0;
          let end = -1;
          for (let i = blockStart; i < code.length; i++) {
            if (code[i] === "{") braceCount++;
            if (code[i] === "}") braceCount--;
            if (braceCount === 0) {
              end = i;
              break;
            }
          }
          // if no match found, return the original code
          if (end === -1) return code;

          const body = code.slice(blockStart + 1, end).trim();
          if (!body) return code;

          // Wrap it back into a small function so the snippet looks like a normal
          // Storybook render function.
          return `() => {
    ${body}
}`;
        },
      },
    },
  },
  decorators: [
    (Story, context) => {
      // TODO: read theme variable from localstorage
      // const [globals, updateGlobals] = useGlobals();
      // // updateGlobals({ theme: })
      // console.log(globals)
      // console.log('context.globals.theme', context.globals.theme)
      const selectedTheme =
        context.globals.theme || localStorage.getItem("ds-theme") || "airbus";
      localStorage.setItem("ds-theme", selectedTheme);
      const isCanvas = context.viewMode === "story";
      return (
        <ThemeProvider brand={selectedTheme}>
          {isCanvas ? (
            // Canvas-only wrapper: give focus rings 16px space on all sides and avoid focus ring getting obstructed.
            <div
              style={{ padding: 16, overflow: "visible", boxSizing: "border-box" }}
            >
              <Story />
            </div>
          ) : (
            <Story />
          )}
        </ThemeProvider>
      );
    },
  ],
};

export default preview;
